#include <iostream>
using namespace std;
long long gcd(long long a, long long b){while(b){long long t=a%b;a=b;b=t;}return a;}
int main(){
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int T; if(!(cin>>T)) return 0;
    while(T--){
        long long N,D,K; cin>>N>>D>>K;
        long long g=gcd(N,D); long long L=N/g;
        long long t=K-1; long long r=t/L; long long i=t%L;
        long long ans=(r+i*D)%N;
        cout<<ans<<'\n';
    }
    return 0;
}

