#include <iostream>
#include <set>
#include <vector>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N, M, K;
    cin >> N >> M >> K;
    vector<long long> A(N);
    for (int i=0; i<N; ++i) cin >> A[i];
    multiset<long long> small, large;
    long long small_sum = 0;
    for (int i=0; i<M; ++i) large.insert(A[i]);
    while ((int)small.size() < K) {
        auto it = large.begin();
        small.insert(*it); small_sum += *it; large.erase(it);
    }
    vector<long long> ans;
    ans.push_back(small_sum);
    for (int i=1; i<=N-M; ++i) {
        long long rem = A[i-1];
        auto it = small.find(rem);
        if (it != small.end()) {
            small.erase(it);
            small_sum -= rem;
        } else {
            large.erase(large.find(rem));
        }
        long long add = A[i+M-1];
        large.insert(add);
        while ((int)small.size() < K) {
            auto itl = large.begin();
            small.insert(*itl); small_sum += *itl; large.erase(itl);
        }
        while (!large.empty() && !small.empty() && *small.rbegin() > *large.begin()) {
            long long smax = *small.rbegin();
            long long lmin = *large.begin();
            small.erase(small.find(smax));
            large.erase(large.find(lmin));
            small.insert(lmin);
            large.insert(smax);
            small_sum = small_sum - smax + lmin;
        }
        ans.push_back(small_sum);
    }
    for (int i=0; i<(int)ans.size(); ++i) {
        cout << ans[i] << (i+1==(int)ans.size()? "" : " ");
    }
    cout << endl;
    return 0;
}

