import sys
from collections import deque

def main():
    input = sys.stdin.read
    data = input().split()
    if not data: return
    N = int(data[0])
    adj = [[] for _ in range(N+1)]
    deg = [0]*(N+1)
    idx = 1
    for _ in range(N-1):
        u = int(data[idx]); v = int(data[idx+1]); idx += 2
        adj[u].append(v); adj[v].append(u)
        deg[u] += 1; deg[v] += 1
    is_center = [False]*(N+1)
    q = deque()
    for i in range(1, N+1):
        if deg[i] >= 3:
            is_center[i] = True
            q.append(i)
    for i in range(1, N+1):
        if deg[i] == 1:
            nb = adj[i][0]
            if not is_center[nb]:
                is_center[nb] = True
                q.append(nb)
    while q:
        c = q.popleft()
        for n1 in adj[c]:
            if deg[n1] == 1:
                continue
            if deg[n1] == 2:
                n2 = adj[n1][0] if adj[n1][0] != c else adj[n1][1]
                if deg[n2] != 2:
                    continue
                c2 = adj[n2][0] if adj[n2][0] != n1 else adj[n2][1]
                if not is_center[c2]:
                    is_center[c2] = True
                    q.append(c2)
    res = [deg[i] for i in range(1, N+1) if is_center[i]]
    res.sort()
    print(' '.join(map(str, res)))

if __name__ == '__main__':
    main()

