import sys
MOD=998244353
def solve():
    data=sys.stdin.read().split()
    if not data: return
    N=int(data[0]); S=data[1].strip()
    lst=[]
    for ch in S:
        c=int(ch)
        if lst and lst[-1][0]==c: lst[-1][1]+=1
        else: lst.append([c,1])
    steps=0
    while True:
        total=sum(k for c,k in lst)
        if total==1:
            print(steps%MOD); return
        if len(lst)==1:
            c,k=lst[0]
            if c==1:
                print((steps+k-1)%MOD); return
            else:
                if k>1: print(-1); return
                else: print(steps%MOD); return
        new=[]
        for i in range(len(lst)):
            c,k=lst[i]
            cnt=(k-1)*c
            if i+1<len(lst): cnt+=lst[i+1][0]
            if cnt>0:
                if new and new[-1][0]==c: new[-1][1]+=cnt
                else: new.append([c,cnt])
        lst=new
        steps+=1
        if steps>2*N+10 or sum(k for c,k in lst)>10**7:
            print(-1); return
if __name__=='__main__':
    solve()

