        c=int(ch)
        if lst and lst[-1][0]==c: lst[-1][1]+=1
        else: lst.append([c,1])
    steps=0
    while True:
        if len(lst)==1:
            c,k=lst[0]
            if c==1:
                steps=(steps+k-1)%MOD
            else:
                if k>1: print(-1); return
                else: steps%=MOD
            print(steps); return
        total=sum(k for c,k in lst)
        if total==1:
            print(steps%MOD); return
        c_last,k_last=lst[-1]
        if c_last>1:
            if k_last>1:
                print(-1); return
            # k_last==1, single step removes it
            new=[]
            for i in range(len(lst)-1):
                c,k=lst[i]
                cnt=(k-1)*c + lst[i+1][0]
                if cnt>0:
                    if new and new[-1][0]==c: new[-1][1]+=cnt
                    else: new.append([c,cnt])
            lst=new
            steps=(steps+1)%MOD
        else: # c_last==1
            t=k_last
            # update front with c_next=1
            for i in range(len(lst)-1):
                c,k=lst[i]
                if c==1:
                    lst[i][1] = k + t*(lst[i+1][0]-1)
                else:
                    if t>60:
                        print(-1); return
                    ct=c**t
                    if ct>10**18: print(-1); return
                    val = ct*k + (lst[i+1][0]-c)*(ct-1)//(c-1)
                    if val>10**18: print(-1); return
                    lst[i][1]=val
            lst.pop()
            steps=(steps+t)%MOD
