#include <iostream>
#include <vector>
using namespace std;

vector<vector<int>> adj;
long long S = 0;
int cnt0 = 0;

void dfs(int u, int p, int d, vector<int>& sz) {
    sz[u] = 1;
    if (d % 2 == 0) cnt0++;
    int total = (int)adj.size() - 1; // 实际节点数 n，而非 n+1
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs(v, u, d + 1, sz);
        sz[u] += sz[v];
        S += (long long)sz[v] * (total - sz[v]);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    if (!(cin >> n)) return 0;
    adj.resize(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> sz(n + 1, 0);
    dfs(1, 0, 0, sz);
    long long cnt1 = n - cnt0;
    long long ans = (S + (long long)cnt0 * cnt1) / 2;
    cout << ans << endl;
    return 0;
}

