#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;
using ll = long long;

ll floor_sqrt(ll x) {
    ll s = (ll)sqrtl(x);
    while (s * s > x) s--;
    while ((s + 1) * (s + 1) <= x) s++;
    return s;
}

ll ceil_sqrt(ll x) {
    ll s = floor_sqrt(x);
    if (s * s == x) return s;
    return s + 1;
}

ll floor_b(ll x) {
    ll s = floor_sqrt(4 * x + 1);
    return (s - 1) / 2;
}

ll ceil_b(ll x) {
    ll k = floor_b(x);
    if (k * (k + 1) < x) k++;
    return k;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        ll l, r; cin >> l >> r;
        ll ka_min = ceil_sqrt(l), ka_max = floor_sqrt(r);
        ll cntA = (ka_min <= ka_max) ? ka_max - ka_min + 1 : 0;
        ll kb_min = ceil_b(l), kb_max = floor_b(r);
        ll cntB = (kb_min <= kb_max) ? kb_max - kb_min + 1 : 0;
        ll kc_min = ceil_sqrt(l + 1) - 1, kc_max = floor_sqrt(r + 1) - 1;
        ll cntC = (kc_min <= kc_max) ? kc_max - kc_min + 1 : 0;
        cout << cntA + cntB + cntC << "\n";
    }
    return 0;
}

