#include <bits/stdc++.h>
using namespace std;
using ll = long long;

ll gcd(ll a, ll b) { return b ? gcd(b, a % b) : a; }

void solve() {
    int n; cin >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    if (n == 1) { cout << "1\n"; return; }
    vector<ll> b(n-1);
    for (int i = 0; i < n-1; i++) b[i] = abs(a[i+1] - a[i]);
    int ans = 1;
    vector<pair<ll, int>> prev;
    for (ll v : b) {
        vector<pair<ll, int>> cur;
        for (auto &p : prev) {
            ll g = gcd(p.first, v);
            if (g >= 2) {
                if (cur.empty() || cur.back().first != g) cur.push_back({g, p.second + 1});
                else cur.back().second = max(cur.back().second, p.second + 1);
            }
        }
        if (v >= 2) {
            if (cur.empty() || cur.back().first != v) cur.push_back({v, 1});
            // else: same gcd already present with length >=1, keep longer one
        }
        for (auto &p : cur) ans = max(ans, p.second + 1);
        prev = move(cur);
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}

修正说明：原代码在合并相同 gcd 时直接覆盖长度为新值，且单独加入 v 时若 gcd 相等会覆写为 1，导致丢失更长段。现改为对于 prev 合并取 max 长度，且单独加入 v 时不覆盖已有更长段。

