#include <bits/stdc++.h>
using namespace std;
struct Seg {
    int n;
    vector<int> cnt, len;
    Seg(int n): n(n), cnt(4*n,0), len(4*n,0) {}
    void push(int u, int l, int r) {
        if(cnt[u]) len[u] = r-l+1;
