完整C++代码：
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    string s;
    cin >> s;
    struct Router { int L, R, cost; };
    vector<Router> routers;
    for (int i = 1; i <= n; ++i) {
        if (s[i-1] == '1') {
            int L = max(1, i - k);
            int R = min(n, i + k);
            routers.push_back({L, R, i});
        }
    }
    sort(routers.begin(), routers.end(), [](const Router& a, const Router& b) {
        return a.L < b.L;
    });
    vector<long long> dp(n+1, 0);
    using P = pair<long long, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    int ptr = 0;
    for (int i = 1; i <= n; ++i) {
        while (ptr < (int)routers.size() && routers[ptr].L <= i) {
            int L = routers[ptr].L;
            long long cost = dp[L-1] + routers[ptr].cost;
            pq.push({cost, routers[ptr].R});
            ++ptr;
        }
        while (!pq.empty() && pq.top().second < i) pq.pop();
        dp[i] = dp[i-1] + i;
        if (!pq.empty()) dp[i] = min(dp[i], pq.top().first);
    }
    cout << dp[n] << "\n";
    return 0;
}

