#include <bits/stdc++.h>
using namespace std;

// 返回 suf 数组：suf[i] = 子数组 i..n-1 的匹配数
vector<int> get_suf(const vector<int>& a, const vector<int>& b) {
    int n = a.size();
    vector<int> suf(n, 0);
    if (n == 0) return suf;
    unordered_set<int> A, B;
    A.insert(a[n-1]); B.insert(b[n-1]);
    bool common = (a[n-1] == b[n-1]);
    int right = common ? n-1 : -1;
    suf[n-1] = right >= n-1 ? 1 : 0;
    for (int i = n-2; i >= 0; --i) {
        bool new_common = common || A.count(a[i]) || B.count(b[i]) || (a[i] == b[i]);
        swap(A, B);
        A.insert(a[i]);
        B.insert(b[i]);
        common = new_common;
        if (common && right == -1) right = i;
        suf[i] = (right != -1 && right >= i) ? right - i + 1 : 0;
    }
    return suf;
}

void solve() {
    int n; cin >> n;
    vector<int> a(n), b(n);
    for (int i=0;i<n;++i) cin>>a[i];
    for (int i=0;i<n;++i) cin>>b[i];
    vector<int> suf = get_suf(a, b);
    vector<int> ra(a.rbegin(), a.rend()), rb(b.rbegin(), b.rend());
    vector<int> rev_suf = get_suf(ra, rb);
    vector<int> pref(n, 0);
    for (int k=0; k<n; ++k) pref[k] = rev_suf[n-1-k];
    int ans = suf[0];
    for (int p=0; p<n; ++p) {
        int left = (p>0 ? pref[p-1] : 0);
        int right = (p+1<n ? suf[p+1] : 0);
        ans = max(ans, left + right);
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}

