#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n; cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    unordered_set<int> A, B;          // normal state
    bool common = false;
    int ans_no = 0;

    unordered_set<int> A2, B2;        // skip state
    bool common2 = false;
    bool skipped = false;
    int ans_skip = 0;

    for (int i = n - 1; i >= 0; --i) {
        // if we haven't skipped yet, we can skip current i: skip state keeps previous normal state
        if (!skipped) {
            A2 = A; B2 = B; common2 = common;
            skipped = true;
        } else {
            // already skipped earlier, update skip state with i
            bool nc = common2 || A2.count(a[i]) || B2.count(b[i]) || (a[i] == b[i]);
            swap(A2, B2);
            A2.insert(a[i]);
            B2.insert(b[i]);
            common2 = nc;
        }

        // update normal state with i
        bool nc = common || A.count(a[i]) || B.count(b[i]) || (a[i] == b[i]);
        swap(A, B);
        A.insert(a[i]);
        B.insert(b[i]);
        common = nc;

        if (common) ans_no = i + 1;          // i is original index, new index = i
        if (common2) ans_skip = i + 1;      // skipped at some q>i, new index = i
    }

    cout << max(ans_no, ans_skip) << "\n";
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}

