#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n; cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    unordered_set<int> Sa, Sb;
    int ans1 = 0;
    unordered_set<int> Sa2, Sb2;
    bool activated = false;
    int ans2 = 0;

    for (int i = n - 1; i >= 0; --i) {
        // skip state: if not activated, skip current i (inherit normal state)
        if (!activated) {
            Sa2 = Sa; Sb2 = Sb;
            activated = true;
        } else {
            bool match2 = (a[i] == b[i]) || Sa2.count(b[i]) || Sb2.count(a[i]);
            if (!match2) {
                for (int x : Sa2) if (Sb2.count(x)) { match2 = true; break; }
            }
            if (match2 && !ans2) ans2 = i + 1;
            swap(Sa2, Sb2);
            Sa2.insert(b[i]);
            Sb2.insert(a[i]);
        }

        // normal state
        bool match1 = (a[i] == b[i]) || Sa.count(b[i]) || Sb.count(a[i]);
        if (!match1) {
            for (int x : Sa) if (Sb.count(x)) { match1 = true; break; }
        }
        if (match1 && !ans1) ans1 = i + 1;
        swap(Sa, Sb);
