import sys
sys.setrecursionlimit(10000)

def solve():
    a = sys.stdin.readline().strip()
    b = sys.stdin.readline().strip()
    cnt = [0]*10
    for ch in a:
        cnt[int(ch)] += 1
    n = len(a)
    if n < len(b):
        res = []
        for d in range(9, -1, -1):
            if cnt[d] > 0:
                res.append(str(d)*cnt[d])
        print(''.join(res))
        return
    path = []
    def dfs(pos, tight):
        if pos == n:
            return True
        limit = int(b[pos]) if tight else 9
        for d in range(limit, -1, -1):
            if pos == 0 and d == 0:
                continue
            if cnt[d] > 0:
                cnt[d] -= 1
                path.append(str(d))
                if dfs(pos+1, tight and d == limit):
                    return True
                path.pop()
                cnt[d] += 1
        return False
    dfs(0, True)
    print(''.join(path))

if __name__ == '__main__':
    solve()

