#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n, k, d;
    cin >> n >> k >> d;
    if (k == 1) {
        if (n > 1) { cout << -1 << endl; return 0; }
    } else {
        long long ways = 1;
        for (int i = 0; i < d; i++) {
            if (ways >= n) break;
            ways *= k;
        }
        if (ways < n) { cout << -1 << endl; return 0; }
    }
    vector<vector<int>> assign(d, vector<int>(n));
    for (int j = 0; j < n; j++) {
        int tmp = j;
        vector<int> dig(d);
        for (int i = 0; i < d; i++) {
            dig[i] = tmp % k;
            tmp /= k;
        }
        for (int i = 0; i < d; i++) {
            assign[i][j] = dig[d-1-i] + 1;
        }
    }
    for (int i = 0; i < d; i++) {
        for (int j = 0; j < n; j++) {
            cout << assign[i][j] << (j == n-1 ? '\n' : ' ');
        }
    }
    return 0;
}

