#include <bits/stdc++.h>
using namespace std;
const int MAXN = 200005;
int a[MAXN];
int st[20][MAXN];
int maxP[MAXN];
int query(int l, int r) {
    int k = 31 - __builtin_clz(r - l + 1);
    return max(st[k][l], st[k][r - (1 << k) + 1]);
}
void solve() {
    int n; cin >> n;
    for (int i = 1; i <= n; i++) { cin >> a[i]; st[0][i] = a[i]; }
    for (int k = 1; k < 20; k++)
        for (int i = 1; i + (1 << k) - 1 <= n; i++)
            st[k][i] = max(st[k-1][i], st[k-1][i + (1 << (k-1))]);
    int m; cin >> m;
    fill(maxP + 1, maxP + n + 2, 0);
    for (int i = 0; i < m; i++) {
        int p, s; cin >> p >> s;
        maxP[s] = max(maxP[s], p);
    }
    for (int i = n - 1; i >= 1; i--) maxP[i] = max(maxP[i], maxP[i+1]);
    int mx = 0;
    for (int i = 1; i <= n; i++) mx = max(mx, a[i]);
    if (maxP[1] < mx) { cout << -1 << "\n"; return; }
    int days = 0, pos = 1;
    while (pos <= n) {
        int low = 1, high = n - pos + 1, best = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (maxP[mid] >= query(pos, pos + mid - 1)) { best = mid; low = mid + 1; }
            else high = mid - 1;
        }
        if (best == 0) { days = -1; break; }
        pos += best; days++;
    }
    cout << days << "\n";
}
