#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> pal;

void gen_pal(ll MAXV) {
    pal.push_back(1);
    for (int len = 1; len <= 10; ++len) {
        int half = (len + 1) / 2;
        ll start = (len == 1) ? 2 : (ll)pow(10, half - 1);
        ll end = (ll)pow(10, half);
        for (ll i = start; i < end; ++i) {
            string s = to_string(i);
            string t = s; reverse(t.begin(), t.end());
            if (len % 2 == 1) t = t.substr(1);
            ll val = stoll(s + t);
            if (val <= MAXV) pal.push_back(val);
        }
    }
    sort(pal.begin(), pal.end());
}

int main() {
    ll p, q; if (!(cin >> p >> q)) return 0;
    ll MAXV = 3000000000LL;
    gen_pal(MAXV);
    ll ans = 0;
    if (q * 0 <= p * 1) ans = 1; // n=1
    int sq = sqrt(MAXV);
    vector<bool> isp(sq + 1, true);
    vector<int> primes;
    for (int i = 2; i <= sq; ++i) {
        if (isp[i]) {
            primes.push_back(i);
            for (ll j = (ll)i * i; j <= sq; j += i) isp[j] = false;
        }
    }
    ll cnt = 0, rub = 1; // rub=1 because 1 is palindromic
    size_t idx = 0; // pal[0]=1 already counted
    if (idx < pal.size() && pal[idx] == 1) idx++;
    ll seg = 1000000;
    for (ll low = 2; low <= MAXV; low += seg) {
        ll high = min(low + seg - 1, MAXV);
        vector<bool> block(seg, true);
        for (int pr : primes) {
            ll st = max((ll)pr * pr, ((low + pr - 1) / pr) * pr);
            for (ll j = st; j <= high; j += pr) block[j - low] = false;
        }
        for (ll j = low; j <= high; ++j) {
            if (idx < pal.size() && pal[idx] == j) { rub++; idx++; }
            if (block[j - low]) cnt++;
            if (q * cnt <= p * rub) ans = j;
        }
    }
    if (ans >= MAXV) cout << "Palindromic tree is better than splay tree\n";
    else cout << ans << "\n";
    return 0;
}

