    vector<int> parent(n+1, 0), temp(n+1);
    vector<vector<int>> child(n+1);
    int root = 0;
    for (int i = 1; i <= n; ++i) {
        cin >> parent[i] >> temp[i];
        if (parent[i] == 0) root = i;
        else child[parent[i]].push_back(i);
    }
    long long total = 0;
    for (int i = 1; i <= n; ++i) total += temp[i];
    if (total % 3 != 0) {
        cout << -1 << "\n";
        return 0;
    }
    long long S = total / 3;
    vector<long long> sub(n+1, 0);
    for (int i = 1; i <= n; ++i) sub[i] = temp[i];
    vector<int> tin(n+1), tout(n+1);
    int timer = 0;
    stack<pair<int,int>> st;
    st.push({root, 0});
    while (!st.empty()) {
        auto [u, state] = st.top(); st.pop();
        if (state == 0) {
            tin[u] = ++timer;
            st.push({u, 1});
            for (int v : child[u]) st.push({v, 0});
        } else {
            tout[u] = timer;
            if (parent[u] != 0) sub[parent[u]] += sub[u];
        }
    }
    vector<int> A;
    for (int i = 1; i <= n; ++i) {
        if (i != root && sub[i] == S) A.push_back(i);
    }
    sort(A.begin(), A.end(), [&](int a, int b) { return tin[a] < tin[b]; });
    auto is_anc = [&](int u, int v) { return tin[u] <= tin[v] && tout[u] >= tout[v]; };
    if (A.size() >= 2) {
        int u = A[0];
        for (size_t i = 1; i < A.size(); ++i) {
            int v = A[i];
            if (!is_anc(u, v)) {
                cout << u << " " << v << "\n";
                return 0;
            }
        }
    }
    for (int y : A) {
        int x = parent[y];
        while (x != 0) {
            if (x != root && sub[x] == 2 * S) {
                cout << x << " " << y << "\n";
                return 0;
            }
            x = parent[x];
        }
    }
    cout << -1 << "\n";
    return 0;
}

