struct Point { double x,y,z; Point(){} Point(double x,double y,double z):x(x),y(y),z(z){} };
double dist2(const Point& a, const Point& b){double dx=a.x-b.x,dy=a.y-b.y,dz=a.z-b.z;return dx*dx+dy*dy+dz*dz;}
Point operator+(const Point&a,const Point&b){return Point(a.x+b.x,a.y+b.y,a.z+b.z);}
Point operator-(const Point&a,const Point&b){return Point(a.x-b.x,a.y-b.y,a.z-b.z);}
Point operator*(const Point&a,double t){return Point(a.x*t,a.y*t,a.z*t);}
double dot(const Point&a,const Point&b){return a.x*b.x+a.y*b.y+a.z*b.z;}
struct Ball { Point c; double r; Ball():r(-1){} bool contains(const Point&p,double e=1e-9)const{return r>=0 && dist2(c,p)<=r*r+e;} };
Ball makeBall1(const Point&a){Ball ball; ball.c=a; ball.r=0; return ball;}
Ball makeBall2(const Point&a,const Point&b){Ball ball; ball.c=(a+b)*0.5; ball.r=sqrt(dist2(a,b))*0.5; return ball;}
Ball makeBall3(const Point&a,const Point&b,const Point&c){Point ba=b-a,ca=c-a;double A=dot(ba,ba),B=dot(ba,ca),C=dot(ca,ca);double D=0.5*A,E=0.5*C;double det=A*C-B*B;if(fabs(det)<1e-12){Ball b1=makeBall2(a,b),b2=makeBall2(b,c),b3=makeBall2(a,c);if(b1.r<b2.r)b1=b2;if(b3.r<b1.r)b1=b3;return b1;}double u=(D*C-B*E)/det,v=(A*E-B*D)/det;Point center=a+ba*u+ca*v;Ball ball; ball.c=center; ball.r=sqrt(dist2(center,a)); return ball;}
Ball makeBall4(const Point&a,const Point&b,const Point&c,const Point&d){double eq[3][4];Point p[3]={b-a,c-a,d-a};for(int i=0;i<3;++i){eq[i][0]=p[i].x;eq[i][1]=p[i].y;eq[i][2]=p[i].z;eq[i][3]=0.5*(p[i].x*p[i].x+p[i].y*p[i].y+p[i].z*p[i].z);}for(int col=0;col<3;++col){int piv=col;for(int r=col+1;r<3;++r)if(fabs(eq[r][col])>fabs(eq[piv][col]))piv=r;if(fabs(eq[piv][col])<1e-12){Ball arr[4]={makeBall3(a,b,c),makeBall3(a,b,d),makeBall3(a,c,d),makeBall3(b,c,d)};Ball best;best.r=-1;for(int i=0;i<4;++i)if(arr[i].contains(a)&&arr[i].contains(b)&&arr[i].contains(c)&&arr[i].contains(d))if(best.r<0||arr[i].r<best.r)best=arr[i];if(best.r<0)best=arr[0];return best;}swap(eq[col],eq[piv]);double div=eq[col][col];for(int j=col;j<4;++j)eq[col][j]/=div;for(int r=0;r<3;++r)if(r!=col){double f=eq[r][col];for(int j=col;j<4;++j)eq[r][j]-=f*eq[col][j];}}Point oc=a+Point(eq[0][3],eq[1][3],eq[2][3]);Ball ball; ball.c=oc; ball.r=sqrt(dist2(oc,a)); return ball;}
Ball welzl(vector<Point>&P,int n,vector<Point>&R){if(n==0||R.size()==4){if(R.size()==0)return Ball();if(R.size()==1)return makeBall1(R[0]);if(R.size()==2)return makeBall2(R[0],R[1]);if(R.size()==3)return makeBall3(R[0],R[1],R[2]);return makeBall4(R[0],R[1],R[2],R[3]);}Ball B=welzl(P,n-1,R);if(B.contains(P[n-1]))return B;R.push_back(P[n-1]);Ball res=welzl(P,n-1,R);R.pop_back();return res;}
