#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <algorithm>
using namespace std;
const double eps = 1e-9;
struct Point {
    double x, y;
    Point() {}
    Point(double x, double y) : x(x), y(y) {}
    Point operator+(const Point& o) const { return Point(x+o.x, y+o.y); }
    Point operator-(const Point& o) const { return Point(x-o.x, y-o.y); }
    Point operator*(double d) const { return Point(x*d, y*d); }
    double cross(const Point& o) const { return x*o.y - y*o.x; }
    double dot(const Point& o) const { return x*o.x + y*o.y; }
    double dist(const Point& o) const { return hypot(x-o.x, y-o.y); }
};
bool onSeg(Point a, Point b, Point p) {
    if (fabs((b-a).cross(p-a)) > eps) return false;
    double dot = (p-a).dot(b-a);
    if (dot < -eps) return false;
    if (dot > (b-a).dot(b-a)+eps) return false;
    return true;
}
bool inPoly(const vector<Point>& poly, Point p) {
    int n = poly.size();
    for (int i=0; i<n; ++i) if (onSeg(poly[i], poly[(i+1)%n], p)) return false;
    for (int i=0; i<n; ++i) if ((poly[(i+1)%n]-poly[i]).cross(p-poly[i]) < -eps) return false;
    return true;
}
int main() {
    double xs, ys, xe, ye; cin >> xs >> ys >> xe >> ye;
    Point S(xs,ys), T(xe,ye);
    int n; cin >> n;
    vector<Point> poly(n);
    for (int i=0; i<n; ++i) cin >> poly[i].x >> poly[i].y;
    vector<pair<double,Point>> inter;
    for (int i=0; i<n; ++i) {
        Point a=poly[i], b=poly[(i+1)%n];
        double den = (T-S).cross(b-a);
        if (fabs(den) < eps) continue;
        double t = (a-S).cross(b-a) / den;
        double u = (a-S).cross(T-S) / den;
        if (t>=-eps && t<=1+eps && u>=-eps && u<=1+eps) {
            Point p = S + (T-S)*t;
            bool dup=false; for(auto& pr:inter) if(p.dist(pr.second)<1e-7) dup=true;
            if(!dup) inter.push_back({t,p});
        }
    }
    if (inter.size() < 2) {
        cout << fixed << setprecision(9) << S.dist(T) << endl; return 0;
    }
    sort(inter.begin(), inter.end(), [](const pair<double,Point>& a, const pair<double,Point>& b){ return a.first < b.first; });
    Point A = inter.front().second, B = inter.back().second;
    double dSA=S.dist(A), dBT=B.dist(T), dAB=A.dist(B);
    bool ab_in = inPoly(poly, (A+B)*0.5);
    double line_cost = dSA + (ab_in ? 2*dAB : dAB) + dBT;
    vector<double> pref(n+1,0);
    for (int i=0;i<n;++i) pref[i+1]=pref[i]+poly[i].dist(poly[(i+1)%n]);
    double perim=pref[n];
    auto getPos=[&](Point p){
        for(int i=0;i<n;++i){ if(onSeg(poly[i],poly[(i+1)%n],p)) return pref[i]+poly[i].dist(p); }
        return 0.0;
    };
    double posA=getPos(A), posB=getPos(B);
    double bound=fabs(posA-posB); bound=min(bound, perim-bound);
    double detour = dSA + bound + dBT;
    cout << fixed << setprecision(9) << min(line_cost, detour) << endl;
    return 0;
}

