修正原剪枝 bug：原代码 while 循环后 h 已使 u*2^{h+1}-1 > n，再判断同一条件恒假。正确做法是取 H = h-1（若 h>0）作为完美子树高度，直接公式处理。
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

ll pow_mod(ll a, ll b) {
    ll r = 1; a %= MOD;
    while (b) { if (b & 1) r = r * a % MOD; a = a * a % MOD; b >>= 1; }
    return r;
}

vector<ll> cnt;

vector<ll> dfs(ll u, ll n) {
    if (u > n) return {};
    int h = 0;
    while (true) {
        __int128 nxt = (__int128)u * (1LL << (h+1)) - 1;
        if (nxt <= n) h++;
        else break;
    }
    if (h > 0) { // perfect subtree of height H = h-1
        int H = h - 1;
        vector<ll> dep(H+1);
        dep[0] = 1;
        for (int d = 1; d <= H; d++) dep[d] = (1LL << d) % MOD;
        for (int a = 0; a <= H; a++) {
            ll La = (a == 0 ? 1 : (1LL << (a-1)) % MOD);
            for (int b = 0; b <= H; b++) {
                ll Rb = (b == 0 ? 1 : (1LL << (b-1)) % MOD);
                if (a == 0 && b == 0) cnt[1] = (cnt[1] + 1) % MOD;
                else if (a == 0) cnt[b+1] = (cnt[b+1] + Rb) % MOD;
                else if (b == 0) cnt[a+1] = (cnt[a+1] + La) % MOD;
                else cnt[a+b+1] = (cnt[a+b+1] + La * Rb) % MOD;
            }
        }
        return dep;
    }
    auto left = dfs(2*u, n);
    auto right = dfs(2*u+1, n);
    int maxd = 1 + max(left.size(), right.size());
    vector<ll> dep(maxd);
    dep[0] = 1;
    for (int d = 1; d < maxd; d++) {
        ll x = 0;
        if (d-1 < (int)left.size()) x += left[d-1];
        if (d-1 < (int)right.size()) x += right[d-1];
        dep[d] = x % MOD;
    }
    int hl = left.size(), hr = right.size();
    for (int a = 0; a <= hl; a++) {
        ll La = (a == 0 ? 1 : left[a-1]);
        for (int b = 0; b <= hr; b++) {
            ll Rb = (b == 0 ? 1 : right[b-1]);
            if (a == 0 && b == 0) cnt[1] = (cnt[1] + 1) % MOD;
            else if (a == 0) cnt[b+1] = (cnt[b+1] + Rb) % MOD;
            else if (b == 0) cnt[a+1] = (cnt[a+1] + La) % MOD;
            else cnt[a+b+1] = (cnt[a+b+1] + La * Rb) % MOD;
        }
    }
    return dep;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int t; cin >> t;
    while (t--) {
        ll n, m; cin >> n >> m;
        int MAXL = 130;
        cnt.assign(MAXL, 0);
        dfs(1, n);
        ll ans = 0;
        for (int L = 1; L < MAXL; L++) {
            if (!cnt[L]) continue;
            ll f = 0;
            for (int v = 1; v <= m; v++) {
                ll vl = pow_mod(v, L);
                ll vlm = pow_mod(v-1, L);
                f = (f + 1LL * v * ((vl - vlm + MOD) % MOD)) % MOD;
            }
            ll term = cnt[L] * pow_mod(m, n - L) % MOD * f % MOD;
            ans = (ans + term) % MOD;
        }
        cout << ans << '\n';
    }
    return 0;
}

